) as any;

type View = 'split' | 'map' | 'list';

const DEFAULT_FILTERS = {
    type: ['KAT_KARSILIGI'],
    minSize: 200,
    maxSize: 10000,
    imar: [] as string[],
    minEmsal: 0.8,
    maxEmsal: 3.0,
    fizibiliteOnly: false,
    minScore: 10,
};

